-- Migracja cen TD (teatrdramatyczny.pl/ceny-biletow). Uruchom w Supabase SQL Editor.
-- Model finansowy: średnia ważona stref (waga_i = 1 + 0,3*i). na Woli/Przodownik: 100/80 (jak Mała).

ALTER TABLE productions ADD COLUMN IF NOT EXISTS pricing jsonb;

-- 1) Domyślne stawki wg sceny (dla tytułów spoza bieżącego cennika):
UPDATE productions SET price_normal=90, price_reduced=77, price_last_minute=30, price_category='standard', pricing='{"scena":"Duża Scena","normalne":[120,110,100,80,65],"ulgowe":[105,95,85,70,55],"wejsciowka":30,"srednia_wazona_normalna":90,"srednia_wazona_ulgowa":77,"zrodlo":"domyślne (scena)"}'::jsonb WHERE org_id='22222222-2222-2222-2222-222222222222' AND stage='duza';
UPDATE productions SET price_normal=89, price_reduced=79, price_last_minute=25, price_category='standard', pricing='{"scena":"Scena na Woli","normalne":[100,80],"ulgowe":[90,70],"wejsciowka":25,"srednia_wazona_normalna":89,"srednia_wazona_ulgowa":79,"zrodlo":"domyślne (scena)"}'::jsonb WHERE org_id='22222222-2222-2222-2222-222222222222' AND stage='nawoli';
UPDATE productions SET price_normal=89, price_reduced=79, price_last_minute=25, price_category='mala', pricing='{"scena":"Mała Scena","normalne":[100,80],"ulgowe":[90,70],"wejsciowka":25,"srednia_wazona_normalna":89,"srednia_wazona_ulgowa":79,"zrodlo":"domyślne (scena)"}'::jsonb WHERE org_id='22222222-2222-2222-2222-222222222222' AND stage='mala';
UPDATE productions SET price_normal=89, price_reduced=79, price_last_minute=25, price_category='mala', pricing='{"scena":"Scena Przodownik","normalne":[100,80],"ulgowe":[90,70],"wejsciowka":25,"srednia_wazona_normalna":89,"srednia_wazona_ulgowa":79,"zrodlo":"domyślne (scena)"}'::jsonb WHERE org_id='22222222-2222-2222-2222-222222222222' AND stage='przodownik';

